import { render } from '@solidjs/web';
import { createSignal, createMemo, createOptimistic, action, refresh, Loading } from 'solid-js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A pretend server: it keeps the like count and takes 600ms to save.
const api = {
  likes: 41,
  async read() {
    await sleep(100);
    return api.likes;
  },
  async like(fail) {
    await sleep(600);
    if (fail) throw new Error('Could not save your like.');
    api.likes += 1;
  },
};

function LikeButton() {
  const likes = createMemo(() => api.read());
  const [shown, setShown] = createOptimistic(() => likes());
  const [failNext, setFailNext] = createSignal(false);
  const [error, setError] = createSignal('');

  const like = action(function* (fail) {
    yield api.like(fail);
    refresh(likes);
  });

  const save = () => {
    setError('');
    like(failNext()).catch((err) => setError(err.message));
  };

  return (
    <Loading fallback={<p>Loading...</p>}>
      <button onClick={save}>Like ({shown()})</button>{' '}
      <label>
        <input
          type="checkbox"
          checked={failNext()}
          onChange={(event) => setFailNext(event.currentTarget.checked)}
        />{' '}
        Fail next save
      </label>
      <p role="alert">{error()}</p>
    </Loading>
  );
}

render(() => <LikeButton />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal, createMemo, createOptimistic, action, refresh, Loading } from 'solid-js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A pretend server: it keeps the like count and takes 600ms to save.
const api = {
  likes: 41,
  async read() {
    await sleep(100);
    return api.likes;
  },
  async like(fail) {
    await sleep(600);
    if (fail) throw new Error('Could not save your like.');
